func:
const data = msg.payload;
global.set('thresholdsEquipment', data.equipment);
global.set('thresholdsEnvironment', data.environment);
node.warn(`✅ 임계값 로드 완료 - 설비 ${Object.keys(data.equipment).length}개, 환경 ${Object.keys(data.environment).length}개`);
return null;

const cache = {};
for (const row of msg.payload) {
    cache[row.tag_code] = row.param_id;
}
flow.set('equipParamCache', cache);
node.warn(`✅ 설비 param_id 캐시: ${Object.keys(cache).length}개`);

return null;

const cache = {};
for (const row of msg.payload) {
    cache[row.tag_code] = row.param_id;
}
flow.set('envParamCache', cache);  // ← 키만 envParamCache로
node.warn(`✅ 환경 param_id 캐시: ${Object.keys(cache).length}개`);

return null;

const eqId = msg.topic || 'FURN_01';   // Modbus-Read 노드의 topic을 equipment_id로 사용
const r = msg.payload;

let regs;
if (Array.isArray(r)) regs = r;
else if (r && Array.isArray(r.data)) regs = r.data;
else if (r && Array.isArray(r.buffer)) regs = r.buffer;
else { node.error("⚠️ 레지스터 응답 형식 알 수 없음", msg); return null; }

if (regs.length < 13) { node.error(`⚠️ 부족: ${regs.length}/13`); return null; }

const decode = v => v > 32767 ? v - 65536 : v;

msg.payload = {
    [`${eqId}_STATUS`]: decode(regs[0]),
    [`${eqId}_ALARM`]: decode(regs[1]),
    [`${eqId}_TIME`]: decode(regs[2]),
    [`${eqId}_TEMP`]: decode(regs[3]) / 10,
    [`${eqId}_PRESS`]: decode(regs[4]) / 100,
    [`${eqId}_O2_FLOW`]: decode(regs[5]),
    [`${eqId}_N2_FLOW`]: decode(regs[6]),
    [`${eqId}_OX_THICK`]: decode(regs[7]),
    [`${eqId}_CYCLE_TIME`]: decode(regs[8]),
    [`${eqId}_PROD_COUNT`]: decode(regs[9]),
    [`${eqId}_NG_COUNT`]: decode(regs[10]),
    [`${eqId}_OK_COUNT`]: decode(regs[11]),
    [`${eqId}_IDEAL_CYCLE_TIME`]: decode(regs[12]),
};
return msg;

// 입력: msg.payload = { FURN_01_TEMP: 1002.5, ... }
const cache = flow.get('equipParamCache');
if (!cache) {
    node.error("❌ equipParamCache 없음. Init EQP Cache 실행 필요");
    return null;
}

const rows = [];
for (const [tag, value] of Object.entries(msg.payload)) {
    const paramId = cache[tag];
    if (paramId === undefined) {
        node.warn(`⚠️ ${tag} param_id 없음`);
        continue;
    }
    rows.push(`(${paramId}, ${value}, NOW(3))`);  // ← JS 시간 대신 NOW(3)
}

if (rows.length === 0) return null;

msg.topic = `INSERT INTO equipment_measurements 
             (param_id, measured_value, measured_at) 
             VALUES ${rows.join(', ')}`;
msg.payload = null;
return msg;

// msg.topic: 'PART' / 'TEMP' / 'HUM' / 'AMC' / 'VIB' / 'ESD'
// msg.payload: 30개 레지스터 배열 (3대 × 10 레지스터)

const sensorType = msg.topic;
const r = msg.payload;

let regs;
if (Array.isArray(r)) regs = r;
else if (r && Array.isArray(r.data)) regs = r.data;
else if (r && Array.isArray(r.buffer)) regs = r.buffer;
else { node.error(`⚠️ ${sensorType} 응답 형식 알 수 없음`); return null; }

if (regs.length < 30) {
    node.error(`⚠️ ${sensorType} 레지스터 부족: ${regs.length}/30`);
    return null;
}

// 센서 타입별 레이아웃 (env_sim_v01.py의 SENSOR_SPECS와 일치)
const LAYOUTS = {
    PART: { tags: ['CNT_03', 'CNT_05', 'CNT_10'], scales: [1, 1, 1] },
    TEMP: { tags: ['VAL', 'DELTA', 'SETPOINT'], scales: [100, 100, 100] },
    HUM: { tags: ['VAL', 'DELTA', 'SETPOINT'], scales: [100, 100, 100] },
    AMC: { tags: ['ACID', 'BASE', 'COND'], scales: [1000, 1000, 1000] },
    VIB: { tags: ['VEL_X', 'VEL_Y', 'VEL_Z', 'FREQ'], scales: [10, 10, 10, 10] },
    ESD: { tags: ['VOLT', 'CURR', 'RESIST'], scales: [10, 100, 100] },
};

const layout = LAYOUTS[sensorType];
if (!layout) { node.error(`알 수 없는 센서 타입: ${sensorType}`); return null; }

const decode = v => v > 32767 ? v - 65536 : v;
const result = {};

// 3대 처리 (각 10 레지스터씩)
for (let unit = 1; unit <= 3; unit++) {
    const base = (unit - 1) * 10;
    const sensorId = `ENV_${sensorType}_0${unit}`;

    // 측정값
    for (let i = 0; i < layout.tags.length; i++) {
        const tagCode = `${sensorId}_${layout.tags[i]}`;
        result[tagCode] = decode(regs[base + i]) / layout.scales[i];
    }

    // STATUS, ALARM은 항상 +4, +5
    result[`${sensorId}_STATUS`] = decode(regs[base + 4]);
    result[`${sensorId}_ALARM`] = decode(regs[base + 5]);
}

msg.payload = result;
return msg;

const cache = flow.get('envParamCache');
if (!cache) {
    node.error("❌ envParamCache 없음. Init ENV Cache 실행 필요");
    return null;
}

const rows = [];
for (const [tag, value] of Object.entries(msg.payload)) {
    const paramId = cache[tag];
    if (paramId === undefined) {
        node.warn(`⚠️ ${tag} param_id 없음`);
        continue;
    }
    rows.push(`(${paramId}, ${value}, NOW(3))`);
}

if (rows.length === 0) return null;

msg.topic = `INSERT INTO environment_measurements 
             (param_id, measured_value, measured_at) 
             VALUES ${rows.join(', ')}`;
msg.payload = null;
return msg;

// equip_sim_v02.py NodeID 맵 — OEE v2 (각 설비 13 vars: +OK_COUNT, +IDEAL_CYCLE_TIME)
// ✓ 실제 OPC UA Browse로 검증됨 (2026-05-19): 6 equipments × 13 tags = 78 NodeIDs
const NODEID_MAP = {
    'PECVD_01': {
        'TEMP': 'ns=2;i=3', 'PRESS': 'ns=2;i=4', 'RF_PWR': 'ns=2;i=5',
        'SIH4_FLOW': 'ns=2;i=6', 'N2O_FLOW': 'ns=2;i=7', 'DEP_THICK': 'ns=2;i=8',
        'STATUS': 'ns=2;i=9', 'ALARM': 'ns=2;i=10',
        'CYCLE_TIME': 'ns=2;i=11', 'PROD_COUNT': 'ns=2;i=12', 'NG_COUNT': 'ns=2;i=13',
        'OK_COUNT': 'ns=2;i=14', 'IDEAL_CYCLE_TIME': 'ns=2;i=15',
    },
    'PECVD_02': {
        'TEMP': 'ns=2;i=17', 'PRESS': 'ns=2;i=18', 'RF_PWR': 'ns=2;i=19',
        'SIH4_FLOW': 'ns=2;i=20', 'N2O_FLOW': 'ns=2;i=21', 'DEP_THICK': 'ns=2;i=22',
        'STATUS': 'ns=2;i=23', 'ALARM': 'ns=2;i=24',
        'CYCLE_TIME': 'ns=2;i=25', 'PROD_COUNT': 'ns=2;i=26', 'NG_COUNT': 'ns=2;i=27',
        'OK_COUNT': 'ns=2;i=28', 'IDEAL_CYCLE_TIME': 'ns=2;i=29',
    },
    'PECVD_03': {
        'TEMP': 'ns=2;i=31', 'PRESS': 'ns=2;i=32', 'RF_PWR': 'ns=2;i=33',
        'SIH4_FLOW': 'ns=2;i=34', 'N2O_FLOW': 'ns=2;i=35', 'DEP_THICK': 'ns=2;i=36',
        'STATUS': 'ns=2;i=37', 'ALARM': 'ns=2;i=38',
        'CYCLE_TIME': 'ns=2;i=39', 'PROD_COUNT': 'ns=2;i=40', 'NG_COUNT': 'ns=2;i=41',
        'OK_COUNT': 'ns=2;i=42', 'IDEAL_CYCLE_TIME': 'ns=2;i=43',
    },
    'ETCH_01': {
        'PRESS': 'ns=2;i=46', 'RF_PWR': 'ns=2;i=47', 'CF4_FLOW': 'ns=2;i=48',
        'O2_FLOW': 'ns=2;i=49', 'TEMP': 'ns=2;i=50', 'ETCH_DEP': 'ns=2;i=51',
        'STATUS': 'ns=2;i=52', 'ALARM': 'ns=2;i=53',
        'CYCLE_TIME': 'ns=2;i=54', 'PROD_COUNT': 'ns=2;i=55', 'NG_COUNT': 'ns=2;i=56',
        'OK_COUNT': 'ns=2;i=57', 'IDEAL_CYCLE_TIME': 'ns=2;i=58',
    },
    'ETCH_02': {
        'PRESS': 'ns=2;i=60', 'RF_PWR': 'ns=2;i=61', 'CF4_FLOW': 'ns=2;i=62',
        'O2_FLOW': 'ns=2;i=63', 'TEMP': 'ns=2;i=64', 'ETCH_DEP': 'ns=2;i=65',
        'STATUS': 'ns=2;i=66', 'ALARM': 'ns=2;i=67',
        'CYCLE_TIME': 'ns=2;i=68', 'PROD_COUNT': 'ns=2;i=69', 'NG_COUNT': 'ns=2;i=70',
        'OK_COUNT': 'ns=2;i=71', 'IDEAL_CYCLE_TIME': 'ns=2;i=72',
    },
    'ETCH_03': {
        'PRESS': 'ns=2;i=74', 'RF_PWR': 'ns=2;i=75', 'CF4_FLOW': 'ns=2;i=76',
        'O2_FLOW': 'ns=2;i=77', 'TEMP': 'ns=2;i=78', 'ETCH_DEP': 'ns=2;i=79',
        'STATUS': 'ns=2;i=80', 'ALARM': 'ns=2;i=81',
        'CYCLE_TIME': 'ns=2;i=82', 'PROD_COUNT': 'ns=2;i=83', 'NG_COUNT': 'ns=2;i=84',
        'OK_COUNT': 'ns=2;i=85', 'IDEAL_CYCLE_TIME': 'ns=2;i=86',
    },
};

// NodeID → tag_code 역매핑도 같이 캐시 (Decode 함수에서 사용)
const reverseMap = {};
for (const [eq, tags] of Object.entries(NODEID_MAP)) {
    for (const [tag, nid] of Object.entries(tags)) {
        reverseMap[nid] = `${eq}_${tag}`;
    }
}
flow.set('opcuaNodeIdToTag', reverseMap);

// 78개 분기 발송 (6 equipments × 13 tags)
const messages = [];
for (const [eq, tags] of Object.entries(NODEID_MAP)) {
    for (const [tag, nid] of Object.entries(tags)) {
        messages.push({
            topic: nid,
            datatype: "Double",
            payload: ""
        });
    }
}

return [messages];   // ★ array 반환 = 각 element가 별도 msg로 출력됨

// 입력: msg.topic = NodeID, msg.payload = value
// 출력: null (buffer에 누적만, INSERT는 별도 timer)

const reverseMap = flow.get('opcuaNodeIdToTag');
if (!reverseMap) {
    node.error("❌ NodeID 매핑 없음. Fan-out 노드 먼저 실행 필요");
    return null;
}

const tagCode = reverseMap[msg.topic];
if (!tagCode) {
    node.warn(`Unknown NodeID: ${msg.topic}`);
    return null;
}

// buffer에 누적
const buf = flow.get('opcuaBuffer') || {};
buf[tagCode] = msg.payload;
flow.set('opcuaBuffer', buf);

return null;   // 여기선 INSERT 안 함. Flush가 처리.

const buf = flow.get('opcuaBuffer') || {};
if (Object.keys(buf).length === 0) return null;

flow.set('opcuaBuffer', {});   // 비우기
msg.payload = buf;             // { 'PECVD_01_TEMP': 379, 'PECVD_01_PRESS': 4.5, ... }
return msg;

const cache = flow.get('equipParamCache');
if (!cache) {
    node.error("❌ equipParamCache 없음");
    return null;
}

const rows = [];
const missing = [];
for (const [tag, value] of Object.entries(msg.payload)) {
    const paramId = cache[tag];
    if (paramId === undefined) {
        missing.push(tag);
        continue;
    }
    rows.push(`(${paramId}, ${value}, NOW(3))`);
}

if (missing.length > 0) {
    node.warn(`⚠️ 매핑 실패 ${missing.length}개: ${missing.slice(0, 3).join(', ')}`);
}

if (rows.length === 0) {
    node.warn("⚠️ INSERT 행 0개");
    return null;
}

msg.topic = `INSERT INTO equipment_measurements 
             (param_id, measured_value, measured_at) 
             VALUES ${rows.join(', ')}`;
msg.payload = null;
return msg;

const thresholds = global.get('thresholdsEquipment');
const cache = flow.get('equipParamCache');

if (!thresholds || !cache) {
    node.error("❌ thresholdsEquipment 또는 equipParamCache 없음. INIT 실행 필요");
    return null;
}

const alarmMessages = [];

for (const [tag, value] of Object.entries(msg.payload)) {
    const t = thresholds[tag];
    if (!t) continue;
    if (t.category !== 'PROCESS') continue;

    let severity = null;
    if (t.alarm_max !== null && value > t.alarm_max) severity = 'ERR';
    else if (t.alarm_min !== null && value < t.alarm_min) severity = 'ERR';
    else if (t.normal_max !== null && value > t.normal_max) severity = 'WARN';
    else if (t.normal_min !== null && value < t.normal_min) severity = 'WARN';

    // ★ severity가 null이어도 신호 보냄 (state reset용)
    const paramId = cache[tag];
    if (paramId === undefined) continue;

    alarmMessages.push({
        payload: {
            tag, value, severity,    // ← severity가 null일 수도 있음
            paramId,
            sourceType: 'EQP',
            equipmentName: t.equipment_id,
            tagName: t.name,
            unit: t.unit
        }
    });
}

if (alarmMessages.length === 0) return null;
return [alarmMessages];

const thresholds = global.get('thresholdsEnvironment');
const cache = flow.get('envParamCache');

if (!thresholds || !cache) {
    node.error("❌ thresholdsEnvironment 또는 envParamCache 없음. INIT 실행 필요");
    return null;
}

const alarmMessages = [];

// Compare ENV Thresholds
for (const [tag, value] of Object.entries(msg.payload)) {
    const t = thresholds[tag];
    if (!t) continue;
    if (t.category !== 'MEASUREMENT') continue;

    let severity = null;
    if (t.alarm_max !== null && value > t.alarm_max) severity = 'ERR';
    else if (t.alarm_min !== null && value < t.alarm_min) severity = 'ERR';
    else if (t.normal_max !== null && value > t.normal_max) severity = 'WARN';
    else if (t.normal_min !== null && value < t.normal_min) severity = 'WARN';

    // ★ if (!severity) continue;  ← 이 줄 제거

    const paramId = cache[tag];
    if (paramId === undefined) continue;

    alarmMessages.push({
        payload: {
            tag, value, severity, paramId,
            sourceType: 'ENV',
            equipmentName: t.sensor_id,
            tagName: t.name,
            unit: t.unit
        }
    });
}

if (alarmMessages.length === 0) return null;
return [alarmMessages];

// 입력: msg.payload = { tag, value, severity, paramId, sourceType, ... }
// 같은 severity가 연속이면 dedup (스킵)

const a = msg.payload;
const prev = flow.get(`alarmState_${a.tag}`);

// ★ NORMAL 복귀 처리
if (a.severity === null) {
    if (prev != null) {
        flow.set(`alarmState_${a.tag}`, null);   // state 풀기
    }
    return null;   // INSERT 안 함
}

// 같은 severity면 dedup
if (prev === a.severity) return null;

flow.set(`alarmState_${a.tag}`, a.severity);
return msg;

// 입력: msg.payload = { tag, value, severity, paramId, sourceType, ... }
// 출력: msg.topic = INSERT SQL

const a = msg.payload;
const paramCol = a.sourceType === 'EQP' ? 'equipment_param_id' : 'environment_param_id';
const message = `${a.tag} (${a.tagName}) ${a.severity} 발생 — 현재 ${a.value}${a.unit || ''}`;

msg.topic = `INSERT INTO alarms 
    (source_type, ${paramCol}, occurred_at, severity, message, status,
     triggered_value, occurrence_count, last_occurred_at)
    VALUES 
    ('${a.sourceType}', ${a.paramId}, NOW(3), '${a.severity}', 
     '${message.replace(/'/g, "''")}', 'NEW', ${a.value}, 1, NOW(3))`;
msg.payload = null;
return msg;

// 입력: msg.payload = { tag, value, severity, paramId, sourceType, equipmentName, tagName, unit }
// 출력: msg.topic = alarm/event/{severity}, msg.payload = 알람 객체

const a = msg.payload;

msg.topic = `alarm/event/${a.severity}`;
msg.payload = {
    source_type: a.sourceType,
    tag_code: a.tag,
    equipment_id: a.equipmentName,
    tag_name: a.tagName,
    severity: a.severity,
    triggered_value: a.value,
    unit: a.unit,
    occurred_at: new Date().toISOString(),
    status: 'NEW'
};

// ERR만 retain (브로커에 마지막 메시지 보관 → 백엔드 늦게 연결해도 즉시 받음)
msg.retain = (a.severity === 'ERR');

return msg;

const keys = flow.keys();
let count = 0;
for (const key of keys) {
    if (key.startsWith('alarmState_')) {
        flow.set(key, undefined);
        count++;
    }
}
node.warn(`✅ alarmState_* ${count}개 초기화`);
return null;

// 입력: msg.payload = { FURN_01_STATUS: 2, FURN_01_TEMP: 1000, ... } 모든 태그
// 출력: STATUS/ALARM 카테고리 중 값이 변한 태그만 분기 발송

const thrEqp = global.get('thresholdsEquipment') || {};
const thrEnv = global.get('thresholdsEnvironment') || {};
const thresholds = { ...thrEqp, ...thrEnv };

if (!thresholds) {
    node.error("❌ thresholdsEquipment 없음");
    return null;
}

const STATUS_LABEL = { 0: 'idle', 1: 'run', 2: 'alarm', 3: 'PM' };
const ALARM_LABEL = { 0: '정상', 1: '알람' };

const changes = [];

for (const [tag, value] of Object.entries(msg.payload)) {
    const t = thresholds[tag];
    if (!t) continue;
    if (t.category !== 'STATUS') continue; 

    const prev = flow.get(`statusVal_${tag}`);
    flow.set(`statusVal_${tag}`, value);

    if (prev === undefined) continue;
    if (prev === value) continue;

    const labelMap = (t.category === 'STATUS') ? STATUS_LABEL : ALARM_LABEL;

    changes.push({
        payload: {
            tag,
            equipmentId: t.equipment_id || t.sensor_id,
            prevValue: prev,
            newValue: value,
            prevLabel: labelMap[prev] || `code:${prev}`,
            newLabel: labelMap[value] || `code:${value}`,
        }
    });
}

if (changes.length === 0) return null;
return [changes];

// 입력: msg.payload = { tag, equipmentId, prevValue, newValue, prevLabel, newLabel }
const c = msg.payload;

msg.topic = `INSERT INTO status_change_logs 
    (equipment_id, prev_status, new_status, changed_at)
    VALUES 
    ('${c.equipmentId}', ${c.prevValue}, ${c.newValue}, NOW(3))`;
msg.payload = null;
return msg;

// 입력: msg.payload = { timestamp, TRACK_01_SPIN_RPM: 1760, ..., TRACK_01_STATUS: 1, ... }
// 출력: msg.payload = { TRACK_01_SPIN_RPM: 1760, ... } (timestamp 제거)

const p = msg.payload;
if (!p || typeof p !== 'object') {
    node.warn(`잘못된 payload: ${msg.payload}`);
    return null;
}

const { timestamp, ...tags } = p;
if (Object.keys(tags).length === 0) return null;

msg.payload = tags;
return msg;

// 입력: msg.payload = { FURN_01_TEMP: 1002.5, ... }
const cache = flow.get('equipParamCache');
if (!cache) {
    node.error("❌ equipParamCache 없음. Init EQP Cache 실행 필요");
    return null;
}

const rows = [];
for (const [tag, value] of Object.entries(msg.payload)) {
    const paramId = cache[tag];
    if (paramId === undefined) {
        node.warn(`⚠️ ${tag} param_id 없음`);
        continue;
    }
    rows.push(`(${paramId}, ${value}, NOW(3))`);  // ← JS 시간 대신 NOW(3)
}

if (rows.length === 0) return null;

msg.topic = `INSERT INTO equipment_measurements 
             (param_id, measured_value, measured_at) 
             VALUES ${rows.join(', ')}`;
msg.payload = null;
return msg;

const data = msg.payload;
global.set('thresholdsEquipment', data.equipment);
global.set('thresholdsEnvironment', data.environment);
node.warn(`✅ 임계값 로드 완료 - 설비 ${Object.keys(data.equipment).length}개, 환경 ${Object.keys(data.environment).length}개`);
return null;

const cache = {};
for (const row of msg.payload) {
    cache[row.tag_code] = row.param_id;
}
flow.set('equipParamCache', cache);
node.warn(`✅ 설비 param_id 캐시: ${Object.keys(cache).length}개`);

return null;

const cache = {};
for (const row of msg.payload) {
    cache[row.tag_code] = row.param_id;
}
flow.set('envParamCache', cache);  // ← 키만 envParamCache로
node.warn(`✅ 환경 param_id 캐시: ${Object.keys(cache).length}개`);

return null;

const eqId = msg.topic || 'FURN_01';   // Modbus-Read 노드의 topic을 equipment_id로 사용
const r = msg.payload;

let regs;
if (Array.isArray(r)) regs = r;
else if (r && Array.isArray(r.data)) regs = r.data;
else if (r && Array.isArray(r.buffer)) regs = r.buffer;
else { node.error("⚠️ 레지스터 응답 형식 알 수 없음", msg); return null; }

if (regs.length < 13) { node.error(`⚠️ 부족: ${regs.length}/13`); return null; }

const decode = v => v > 32767 ? v - 65536 : v;

msg.payload = {
    [`${eqId}_STATUS`]: decode(regs[0]),
    [`${eqId}_ALARM`]: decode(regs[1]),
    [`${eqId}_TIME`]: decode(regs[2]),
    [`${eqId}_TEMP`]: decode(regs[3]) / 10,
    [`${eqId}_PRESS`]: decode(regs[4]) / 100,
    [`${eqId}_O2_FLOW`]: decode(regs[5]),
    [`${eqId}_N2_FLOW`]: decode(regs[6]),
    [`${eqId}_OX_THICK`]: decode(regs[7]),
    [`${eqId}_CYCLE_TIME`]: decode(regs[8]),
    [`${eqId}_PROD_COUNT`]: decode(regs[9]),
    [`${eqId}_NG_COUNT`]: decode(regs[10]),
    [`${eqId}_OK_COUNT`]: decode(regs[11]),
    [`${eqId}_IDEAL_CYCLE_TIME`]: decode(regs[12]),
};
return msg;

