// msg.topic: 'PART' / 'TEMP' / 'HUM' / 'AMC' / 'VIB' / 'ESD'
// msg.payload: 30개 레지스터 배열 (3대 × 10 레지스터)

const sensorType = msg.topic;
const r = msg.payload;

let regs;
if (Array.isArray(r)) regs = r;
else if (r && Array.isArray(r.data)) regs = r.data;
else if (r && Array.isArray(r.buffer)) regs = r.buffer;
else { node.error(`⚠️ ${sensorType} 응답 형식 알 수 없음`); return null; }

if (regs.length < 30) {
    node.error(`⚠️ ${sensorType} 레지스터 부족: ${regs.length}/30`);
    return null;
}

// 센서 타입별 레이아웃 (env_sim_v01.py의 SENSOR_SPECS와 일치)
const LAYOUTS = {
    PART: { tags: ['CNT_03', 'CNT_05', 'CNT_10'], scales: [1, 1, 1] },
    TEMP: { tags: ['VAL', 'DELTA', 'SETPOINT'], scales: [100, 100, 100] },
    HUM: { tags: ['VAL', 'DELTA', 'SETPOINT'], scales: [100, 100, 100] },
    AMC: { tags: ['ACID', 'BASE', 'COND'], scales: [1000, 1000, 1000] },
    VIB: { tags: ['VEL_X', 'VEL_Y', 'VEL_Z', 'FREQ'], scales: [10, 10, 10, 10] },
    ESD: { tags: ['VOLT', 'CURR', 'RESIST'], scales: [10, 100, 100] },
};

const layout = LAYOUTS[sensorType];
if (!layout) { node.error(`알 수 없는 센서 타입: ${sensorType}`); return null; }

const decode = v => v > 32767 ? v - 65536 : v;
const result = {};

// 3대 처리 (각 10 레지스터씩)
for (let unit = 1; unit <= 3; unit++) {
    const base = (unit - 1) * 10;
    const sensorId = `ENV_${sensorType}_0${unit}`;

    // 측정값
    for (let i = 0; i < layout.tags.length; i++) {
        const tagCode = `${sensorId}_${layout.tags[i]}`;
        result[tagCode] = decode(regs[base + i]) / layout.scales[i];
    }

    // STATUS, ALARM은 항상 +4, +5
    result[`${sensorId}_STATUS`] = decode(regs[base + 4]);
    result[`${sensorId}_ALARM`] = decode(regs[base + 5]);
}

msg.payload = result;
return msg;

const cache = flow.get('envParamCache');
if (!cache) {
    node.error("❌ envParamCache 없음. Init ENV Cache 실행 필요");
    return null;
}

const rows = [];
